using System;
using System.Drawing;

namespace OpenPmsDental.UI{
	//The pictures of the icons that are not yet Fluent icons (IconLibrary.IsPicture): Chart32G, Chart32W and ChartMed32, until UI-8 of the UI refresh
	//makes the dental icons. Every other EnumIcons draws from the icon table in CodeBase since UI-7b (docs/port-notes/UI-7b.md), which removed
	//their Gen_*.cs files and their lines here. This file was generated by the IconOrganizer project; it is now kept by hand.

	public class IconSelector{
		///<summary>The picture of a picture icon as base64, or "" for every other icon.</summary>
		public static string GetBase64(EnumIcons icon){
			switch(icon){
				case EnumIcons.Chart32G:
					return Gen_Chart32G.GetBase64();
				case EnumIcons.Chart32W:
					return Gen_Chart32W.GetBase64();
				case EnumIcons.ChartMed32:
					return Gen_ChartMed32.GetBase64();
				default:
					return "";
			}
		}
	}
}
